import{_ as e,o as t,c as a,a3 as o}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"语言是窗户（否则，它们是墙）","description":"","frontmatter":{},"headers":[],"relativePath":"books/feibaoli-goutong/06-语言是窗户（否则，它们是墙）.md","filePath":"books/feibaoli-goutong/06-语言是窗户（否则，它们是墙）.md","lastUpdated":1794752249000}'),_={name:"books/feibaoli-goutong/06-语言是窗户（否则，它们是墙）.md"};function r(s,p,n,i,l,d){return t(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="语言是窗户-否则-它们是墙" tabindex="-1">语言是窗户（否则，它们是墙） <a class="header-anchor" href="#语言是窗户-否则-它们是墙" aria-label="Permalink to &quot;语言是窗户（否则，它们是墙）&quot;">​</a></h1><p>听了你的话，我仿佛受了审判，</p><p>无比委屈，又无从分辩，</p><p>在离开前，我想问，</p><p>那真的是你的意思吗？</p><p>在自我辩护前，</p><p>在带着痛苦或恐惧质问前，</p><p>在我用言语筑起心灵之墙前，</p><p>告诉我，我听明白了吗？</p><p>语言是窗户，或者是墙，</p><p>它们审判我们，或者让我们自由。</p><p>在我说与听的时候，</p><p>请让爱的光芒照耀我。</p><p>我心里有话要说，</p><p>那些话对我如此重要，</p><p>如果言语无法传达我的心声，</p><p>请你帮我获得自由好吗？</p><p>如果你以为我想羞辱你，</p><p>如果你认定我不在乎你，</p><p>请透过我的言语，</p><p>倾听我们共有的情感。</p><p>——鲁思·贝本梅尔（Ruth Bebermeyer）</p>',22)])])}const m=e(_,[["render",r]]);export{f as __pageData,m as default};
